import pulp

# Problem definition
model = pulp.LpProblem("fuel_additive_plan", pulp.LpMinimize)

# Parameters
num_days = 18
initial_stock = 30
max_capacity = 37
procurement_cost_per_barrel = 4
storage_cost_per_barrel = 1
penalty_cost_per_barrel = 15
shipment_min = 17
shipment_max = 57

# Daily consumption list (index 0 corresponds to day 1)
consumption = [
    30, 47, 30, 37, 46, 59, 50, 19,
    42, 37, 35, 25, 33, 34, 28, 25, 23, 26
]

# Decision variables
shipments = {
    t: pulp.LpVariable(f"x_{t}", lowBound=shipment_min, upBound=shipment_max, cat='Continuous')
    for t in range(1, num_days + 1)
}
stock = {
    t: pulp.LpVariable(f"s_{t}", lowBound=0, cat='Continuous')
    for t in range(1, num_days + 1)
}
deficit = {
    t: pulp.LpVariable(f"d_{t}", lowBound=0, cat='Continuous')
    for t in range(1, num_days + 1)
}

# Constraints
for t in range(1, num_days + 1):
    # Previous stock level
    prev_stock = initial_stock if t == 1 else stock[t - 1]
    # Arrival from shipment two days earlier
    arrival = 0 if t <= 2 else shipments[t - 2]
    # Stock balance with deficit
    model += (
        prev_stock + arrival - consumption[t - 1]
        == stock[t] - deficit[t]
    ), f"balance_day_{t}"
    # Capacity limit
    model += stock[t] <= max_capacity, f"capacity_day_{t}"

# Objective: minimize total cost
model += (
    pulp.lpSum(
        procurement_cost_per_barrel * shipments[t]
        for t in range(1, num_days + 1)
    )
    + pulp.lpSum(
        storage_cost_per_barrel * stock[t]
        for t in range(1, num_days + 1)
    )
    + pulp.lpSum(
        penalty_cost_per_barrel * deficit[t]
        for t in range(1, num_days + 1)
    )
), "total_cost"

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Total cost: {pulp.value(model.objective):.2f}\n")

print("Day | Shipment | Stock | Deficit")
for t in range(1, num_days + 1):
    print(f"{t:>3} | {shipments[t].varValue:>8.2f} | {stock[t].varValue:>5.2f} | {deficit[t].varValue:>7.2f}")

