import pulp

# ---------- Problem data ----------
patients = {
    'A': [('X', 2), ('Z', 4), ('Y', 6)],
    'B': [('X', 1), ('Y', 2), ('Z', 3)],
    'C': [('Z',10), ('X', 9), ('Y',10)]
}

# All machines
machines = {'X', 'Y', 'Z'}

# Big-M constant (sum of all durations)
M = sum(d for ops in patients.values() for (_, d) in ops)

# ---------- Create model ----------
model = pulp.LpProblem("Hospital_Test_Scheduling", pulp.LpMinimize)

# Start time variables: S_{patient}_{op}
S = {}
for p, ops in patients.items():
    for k, (machine, duration) in enumerate(ops):
        S[(p, k)] = pulp.LpVariable(f"S_{p}_{k}", lowBound=0, cat='Continuous')

# Makespan variable
Cmax = pulp.LpVariable("Cmax", lowBound=0, cat='Continuous')

# ---------- Objective ----------
model += Cmax, "Minimize_makespan"

# ---------- Constraints ----------

# 1. Precedence constraints within each patient
for p, ops in patients.items():
    for k in range(len(ops)-1):
        _, dur_k = ops[k]
        model += S[(p, k+1)] >= S[(p, k)] + dur_k, f"Precedence_{p}_{k}_{k+1}"

# 2. Makespan constraints for each operation
for p, ops in patients.items():
    for k, (_, dur) in enumerate(ops):
        model += S[(p, k)] + dur <= Cmax, f"Cmax_{p}_{k}"

# 3. Non‑overlap constraints on the same machine
#   Build list of operations per machine
ops_by_machine = {m: [] for m in machines}
for p, ops in patients.items():
    for k, (m, d) in enumerate(ops):
        ops_by_machine[m].append((p, k, d))

# Binary sequencing variables for each unordered pair of operations on same machine
x = {}
for m, op_list in ops_by_machine.items():
    n = len(op_list)
    for i in range(n):
        for j in range(i+1, n):
            p_i, k_i, d_i = op_list[i]
            p_j, k_j, d_j = op_list[j]
            var_name = f"x_{p_i}_{k_i}_{p_j}_{k_j}"
            x[(p_i, k_i, p_j, k_j)] = pulp.LpVariable(var_name, cat='Binary')
            # Constraint: either i precedes j or j precedes i
            model += S[(p_i, k_i)] + d_i <= S[(p_j, k_j)] + M * (1 - x[(p_i, k_i, p_j, k_j)])
            model += S[(p_j, k_j)] + d_j <= S[(p_i, k_i)] + M * x[(p_i, k_i, p_j, k_j)]

# ---------- Solve ----------
solver = pulp.HiGHS(msg=False, timeLimit=120)
model.solve(solver)

# ---------- Output ----------
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Minimum makespan: {pulp.value(Cmax)} hours\n")

for p, ops in patients.items():
    for k, (machine, dur) in enumerate(ops):
        start = pulp.value(S[(p, k)])
        print(f"Patient {p}, Operation {k+1} on {machine} (duration {dur}) starts at {start:.2f} hours")

