import pulp

# Problem
model = pulp.LpProblem("TSP_BloodBank", pulp.LpMinimize)

# Nodes
nodes = [0, 1, 2, 3]          # 0 = Center 1 (depot), 1 = Center 2, 2 = Center 3, 3 = Center 4
n = len(nodes)

# Travel times (minutes) – symmetric matrix
travel = {
    (0, 1): 197.5, (0, 2): 251.0, (0, 3): 216.8,
    (1, 2): 98.0,  (1, 3): 59.4,
    (2, 3): 41.2
}

# Decision variables: x[i,j] = 1 if edge (i,j) is used
x = {}
for i in nodes:
    for j in nodes:
        if i < j:
            x[(i, j)] = pulp.LpVariable(f"x_{i}_{j}", cat="Binary")

# Objective: minimize total travel time
model += pulp.lpSum(travel[(i, j)] * x[(i, j)] for (i, j) in x)

# Degree constraints: each node has exactly two incident edges
for i in nodes:
    model += (
        pulp.lpSum(x[(min(i, j), max(i, j))] for j in nodes if j != i) == 2,
        f"Degree_{i}"
    )

# Subtour elimination – Miller–Tucker–Zemlin formulation
# u[0] is fixed at 0; others are continuous variables between 1 and n-1
u = {}
for i in nodes:
    if i == 0:
        u[i] = pulp.LpVariable(f"u_{i}", lowBound=0, upBound=0, cat="Continuous")
    else:
        u[i] = pulp.LpVariable(f"u_{i}", lowBound=1, upBound=n-1, cat="Continuous")

for i in nodes:
    for j in nodes:
        if i != j and i > 0 and j > 0:
            # MTZ constraint
            model += (
                u[i] - u[j] + n * x[(min(i, j), max(i, j))] <= n - 1,
                f"MTZ_{i}_{j}"
            )

# Solve with HiGHS solver
solver = pulp.HiGHS(msg=False, timeLimit=120)
model.solve(solver)

# Output results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Optimal total travel time: {pulp.value(model.objective):.1f} minutes")

# Extract route
used_edges = [(i, j) for (i, j) in x if pulp.value(x[(i, j)]) > 0.5]
print("Used edges:")
for i, j in used_edges:
    print(f"  {i} <-> {j} (time {travel[(i, j)]} min)")

