import pulp

# ---------- Data ----------
# Each truck's route segments: (route, duration)
trucks = {
    1: [(8, 3), (6, 4), (7, 8), (4, 6), (3, 1), (2, 6), (5, 8), (1, 10)],
    2: [(5, 7), (6,10), (2, 6), (1, 9), (8, 3), (7, 1), (4, 8), (3, 7)],
    3: [(8, 8), (7, 3), (4, 2), (3, 9), (1, 9), (6, 7), (5,10), (2, 5)],
    4: [(4, 4), (1,10), (8, 5), (7, 7), (6, 8), (3, 9), (2, 5), (5, 2)],
    5: [(1, 8), (8, 7), (3, 9), (4, 1), (5, 7), (2, 5), (7, 8), (6, 3)],
    6: [(7, 7), (6,10), (4, 3), (8, 6), (3, 1), (2, 7), (5, 8), (1, 8)],
    7: [(5,10), (1, 6), (6, 3), (2, 3), (3, 8), (7, 2), (8, 2), (4, 3)],
    8: [(1, 3), (2, 5), (6, 7), (7, 8), (8, 5), (3, 9), (5, 1), (4, 3)]
}

# ---------- Model ----------
model = pulp.LpProblem("job_shop_schedule", pulp.LpMinimize)

# Big-M value
M = 1000

# ----- Variables -----
# start times: key (truck, segment_index)
start = {}
for t, segs in trucks.items():
    for k, _ in enumerate(segs):
        var = pulp.LpVariable(f"s_{t}_{k}", lowBound=0, cat='Continuous')
        start[(t, k)] = var

# binary variables for ordering on the same route
# key (t1, k1, t2, k2) with t1 < t2 for uniqueness
y = {}
for t1, segs1 in trucks.items():
    for k1, (route1, _) in enumerate(segs1):
        for t2, segs2 in trucks.items():
            if t2 <= t1:  # avoid duplicate and self
                continue
            for k2, (route2, _) in enumerate(segs2):
                if route1 == route2:
                    var = pulp.LpVariable(f"y_{t1}_{k1}_{t2}_{k2}", cat='Binary')
                    y[(t1, k1, t2, k2)] = var

# makespan variable
Cmax = pulp.LpVariable("Cmax", lowBound=0, cat='Continuous')

# ----- Objective -----
model += Cmax, "Minimize_makespan"

# ----- Constraints -----
# 1. Sequential order for each truck
for t, segs in trucks.items():
    for k in range(1, len(segs)):
        prev = start[(t, k-1)]
        curr = start[(t, k)]
        _, p_prev = segs[k-1]
        model += curr >= prev + p_prev, f"seq_truck{t}_seg{k}"

# 2. Machine (route) constraints
for t1, segs1 in trucks.items():
    for k1, (route1, p1) in enumerate(segs1):
        for t2, segs2 in trucks.items():
            if t2 <= t1:
                continue
            for k2, (route2, p2) in enumerate(segs2):
                if route1 == route2:
                    # enforce ordering
                    s1 = start[(t1, k1)]
                    s2 = start[(t2, k2)]
                    var = y[(t1, k1, t2, k2)]
                    # s2 >= s1 + p1 - M*(1 - var)
                    model += s2 >= s1 + p1 - M * (1 - var), f"machine_{route1}_{t1}_{k1}_before_{t2}_{k2}"
                    # s1 >= s2 + p2 - M*var
                    model += s1 >= s2 + p2 - M * var, f"machine_{route1}_{t2}_{k2}_before_{t1}_{k1}"

# 3. Makespan bounds
for t, segs in trucks.items():
